SELECT wtpd.TRADE_ID, #{VALID_STATUS_01} VALID_STATUS, wtpda.ENTRUST_ID, wtpda.PORTFOLIO_ID, pp.PORTFOLIO_NAME, wtpd.FINPROD_TYPE2, wtpd.FINPROD_ID, wtpdo.DL_TYPE as PA_BUSS_TYPE, wptpd.BACK_LEND_DIRECTION as BUSI_PS, wtpd.TRADE_AMT, wtpd.CCY, wtpd.TRADE_DATE, wtpd.REMARK, wtpd.WORKFLOW_ID, wtpd.WORKFLOW_STATUS FROM WFL_TRD_PRODUCT_DEAL wtpd left join WFL_TRD_PRODUCT_DEAL_ADD wtpda on wtpd.TRADE_ID = wtpda.TRADE_ID left join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = wtpda.PORTFOLIO_ID left join WFL_TRD_PRODUCT_DEAL_OTH wtpdo on wtpdo.TRADE_ID = wtpd.TRADE_ID
left join WFL_PA_TRD_PRODUCT_DEAL wptpd on wtpd.TRADE_ID = wptpd.TRADE_ID where wtpd.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F08}, #{FINPROD_TYPE_TG_F09}, #{FINPROD_TYPE_TG_F25}) and wptpd.PA_BUSS_TYPE IN (#{PINAN_BUSINESS_TYPE_14}, #{PINAN_BUSINESS_TYPE_15}, #{PINAN_BUSINESS_TYPE_16})
AND ( pp.PORTFOLIO_ID IN
#{item}
OR pp.PARENT_PORTFOLIO_ID IN
#{item}
)
AND (pp.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) OR pp.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND wtpda.ENTRUST_ID like CONCAT(#{entrustId}, '%')
AND wtpdo.DL_TYPE = #{paBussType}
and wptpd.BACK_LEND_DIRECTION = #{ps}
AND wtpd.TRADE_DATE >= to_date(#{tradeDateBegin}, 'yyyy-MM-dd')
AND wtpd.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
and (wtpd.IS_CANCEL is null or wtpd.IS_CANCEL = #{YES_NO_NO}) and wtpd.TRADE_STATUS = #{TRADE_STATUS_01}
UNION ALL SELECT wtpd.TRADE_ID, #{VALID_STATUS_02} VALID_STATUS, wtpda.ENTRUST_ID, PP.PORTFOLIO_ID, pp.PORTFOLIO_NAME, wtpd.FINPROD_TYPE2, wtpd.FINPROD_ID, fpt.TYPE_6 as PA_BUSS_TYPE, wptpd.BACK_LEND_DIRECTION as BUSI_PS, wtpd.TRADE_AMT, wtpd.CCY, wtpd.TRADE_DATE, wtpd.REMARK, null as WORKFLOW_ID, null as WORKFLOW_STATUS FROM TRD_PRODUCT_DEAL wtpd left join TRD_PRODUCT_DEAL_ADD wtpda on wtpd.TRADE_ID = wtpda.TRADE_ID LEFT JOIN PTL_TRADE PT ON wtpd.TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID left join FIN_PRODUCT_TYPE fpt on (case when wtpd.IS_OUT_TRADE='N' and wtpd.R_TRADE_ID is not null then wtpd.R_TRADE_ID else wtpd.TRADE_ID END) = fpt.FINPROD_ID and fpt.BRANCH = #{BRANCH_0} left join PA_TRD_PRODUCT_DEAL wptpd on wtpd.TRADE_ID = wptpd.TRADE_ID where PP.INVEST_YESORNO = 'Y' AND wtpd.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F08}, #{FINPROD_TYPE_TG_F09}, #{FINPROD_TYPE_TG_F25}) and wptpd.PA_BUSS_TYPE IN (#{PINAN_BUSINESS_TYPE_14}, #{PINAN_BUSINESS_TYPE_15}, #{PINAN_BUSINESS_TYPE_16})
AND ( pp.PORTFOLIO_ID IN
#{item}
OR pp.PARENT_PORTFOLIO_ID IN
#{item}
)
AND (pp.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) OR pp.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND wtpda.ENTRUST_ID like CONCAT(#{entrustId}, '%')
AND fpt.TYPE_6 = #{paBussType}
and wptpd.BACK_LEND_DIRECTION = #{ps}
AND wtpd.TRADE_DATE >= to_date(#{tradeDateBegin}, 'yyyy-MM-dd')
AND wtpd.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
and (wtpd.IS_CANCEL is null or wtpd.IS_CANCEL = #{YES_NO_NO}) and wtpd.TRADE_STATUS = #{TRADE_STATUS_01}
UNION ALL SELECT wtpd.TRADE_ID, #{VALID_STATUS_03} VALID_STATUS, wtpda.ENTRUST_ID, PP.PORTFOLIO_ID, pp.PORTFOLIO_NAME, wtpd.FINPROD_TYPE2, wtpd.FINPROD_ID, fpt.TYPE_6 as PA_BUSS_TYPE, wptpd.BACK_LEND_DIRECTION as BUSI_PS, wtpd.TRADE_AMT, wtpd.CCY, wtpd.TRADE_DATE, wtpd.REMARK, null as WORKFLOW_ID, null as WORKFLOW_STATUS FROM TRD_PRODUCT_DEAL wtpd left join TRD_PRODUCT_DEAL_ADD wtpda on wtpd.TRADE_ID = wtpda.TRADE_ID LEFT JOIN PTL_TRADE PT ON wtpd.TRADE_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID left join FIN_PRODUCT_TYPE fpt on (case when wtpd.IS_OUT_TRADE='N' and wtpd.R_TRADE_ID is not null then wtpd.R_TRADE_ID else wtpd.TRADE_ID END) = fpt.FINPROD_ID and fpt.BRANCH = #{BRANCH_0}
left join PA_TRD_PRODUCT_DEAL wptpd on wtpd.TRADE_ID = wptpd.TRADE_ID where wtpd.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F08}, #{FINPROD_TYPE_TG_F09}, #{FINPROD_TYPE_TG_F25}) and wptpd.PA_BUSS_TYPE IN (#{PINAN_BUSINESS_TYPE_14}, #{PINAN_BUSINESS_TYPE_15}, #{PINAN_BUSINESS_TYPE_16})
AND ( pp.PORTFOLIO_ID IN
#{item}
OR pp.PARENT_PORTFOLIO_ID IN
#{item}
)
AND (pp.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}) OR pp.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))
AND wtpda.ENTRUST_ID like CONCAT(#{entrustId}, '%')
AND fpt.TYPE_6 = #{paBussType}
and wptpd.BACK_LEND_DIRECTION = #{ps}
AND wtpd.TRADE_DATE >= to_date(#{tradeDateBegin}, 'yyyy-MM-dd')
AND wtpd.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
AND PP.INVEST_YESORNO='Y' and wtpd.IS_CANCEL = #{YES_NO_YES} and wtpd.TRADE_STATUS = #{TRADE_STATUS_01}
ORDER BY TRADE_DATE DESC, TRADE_ID DESC

select count(1) from WFL_TRD_PRODUCT_DEAL 
where TRADE_ID = #{tradeId,jdbcType=VARCHAR}
    or P_TRADE_ID = #{tradeId,jdbcType=VARCHAR}

        select sum(num) from (
	        select count(1) num from TRD_FIN_PRODUCT_DEAL_TOTAL 
	        where FINPROD_ID = #{tradeId,jdbcType=VARCHAR}
	        AND TRADE_STATUS = #{tradeStatus,jdbcType=VARCHAR}
	        AND IS_CANCEL = #{isCancel,jdbcType=VARCHAR}
	        UNION ALL
	        select count(1) num from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL
	        where FINPROD_ID = #{tradeId,jdbcType=VARCHAR}
        )

select count(1) from TRD_PRODUCT_DEAL 
where 
    (TRADE_ID = #{tradeId,jdbcType=VARCHAR}
    or P_TRADE_ID = #{tradeId,jdbcType=VARCHAR})
    and 
    (IS_CANCEL = #{YES_NO_YES,jdbcType=VARCHAR}
    or TRADE_STATUS = #{TRADE_STATUS_03,jdbcType=VARCHAR}
    )

select count(1) from LQD_PIPELINE_MATCH 
where 
    SYS_TRADE_ID = #{tradeId,jdbcType=VARCHAR}
